package store

import (
	"context"
	"encoding/json"
	"time"

	"github.com/jackc/pgx/v5"
)

// ArtifactRef names an immutable object; it does not certify that the object
// exists, passed scanning or was generated by an AI. Bytes stay outside outbox.
type ArtifactRef struct {
	ID        string `json:"id"`
	SHA256    string `json:"sha256"`
	SizeBytes int64  `json:"size_bytes"`
}

func (a ArtifactRef) validate() error {
	if !validID.MatchString(a.ID) || !validHash.MatchString(a.SHA256) || a.SizeBytes < 1 || a.SizeBytes > 64*1024*1024 {
		return ErrInvalid
	}
	return nil
}

// Caller owns the project/scope/task locks. A usable checkpoint is a possible
// continuation, never permission to restart a process or adopt a new base.
func reconcileTask(ctx context.Context, tx pgx.Tx, taskID string) error {
	_, err := tx.Exec(ctx, `UPDATE tasks t SET status=CASE WHEN
        NOT EXISTS (SELECT 1 FROM leases l WHERE l.task_id=t.id AND l.state IN ('reserved','active','stop_requested'))
        AND EXISTS (SELECT 1 FROM checkpoints c JOIN task_versions v
            ON (v.task_id,v.version,v.contract_hash)=(t.id,t.current_version,t.current_hash)
            WHERE (c.task_id,c.task_version,c.contract_hash)=(t.id,t.current_version,t.current_hash)
              AND c.status='usable' AND c.expires_at>clock_timestamp()
              AND c.base_commit=v.contract->'workspace'->>'commit'
              AND (v.contract->'handoff'->>'enabled')::boolean
              AND (v.contract->'handoff'->>'resume_from_latest')::boolean)
        THEN 'resumable' ELSE 'open' END
        WHERE t.id=$1 AND t.status NOT IN ('accepted','archived')
          AND NOT EXISTS (SELECT 1 FROM submissions s WHERE s.task_id=t.id
            AND s.status IN ('submitted','verifying','verified_candidate','in_review','accepted'))`, taskID)
	return err
}

// Caller has locked the lease and its budget ancestry in the normal order.
// Ending a lease releases scheduled capacity exactly once; it never accepts a
// submission, awards points or proves that a local process stopped.
func finishLease(ctx context.Context, tx pgx.Tx, lease Lease, now time.Time, state string) (Lease, error) {
	if state != "completed" && state != "released" && state != "expired" {
		return Lease{}, ErrInvalid
	}
	if lease.EndedAt != nil {
		return lease, nil
	}
	if state == "completed" && (lease.State != "active" || !now.Before(lease.ExpiresAt)) {
		return Lease{}, ErrClosed
	}
	if state == "expired" && now.Before(lease.ExpiresAt) {
		return Lease{}, ErrInvalid
	}
	if !now.Before(lease.ExpiresAt) {
		state = "expired"
	}
	lease.SpentMs, lease.OverrunMs = settlement(lease, now)
	lease.State, lease.EndedAt = state, &now
	result, err := tx.Exec(ctx, `UPDATE budget_accounts a SET reserved_ms=a.reserved_ms-b.reserved_ms,spent_ms=a.spent_ms+$2
        FROM lease_budgets b WHERE b.lease_id=$1 AND a.id=b.account_id`, lease.ID, lease.SpentMs)
	if err != nil {
		return Lease{}, err
	}
	if result.RowsAffected() < 2 {
		return Lease{}, ErrInvariant
	}
	result, err = tx.Exec(ctx, `UPDATE leases SET state=$2,ended_at=$3,spent_ms=$4,overrun_ms=$5
        WHERE id=$1 AND ended_at IS NULL`, lease.ID, lease.State, lease.EndedAt, lease.SpentMs, lease.OverrunMs)
	if err != nil {
		return Lease{}, err
	}
	if result.RowsAffected() != 1 {
		return Lease{}, ErrInvariant
	}
	if err = emit(ctx, tx, "lease.ended", lease); err != nil {
		return Lease{}, err
	}
	if err = reconcileTask(ctx, tx, lease.TaskID); err != nil {
		return Lease{}, err
	}
	return lease, nil
}

var domainEventKinds = map[string]bool{
	"submission.submitted": true, "submission.verified": true,
	"submission.rejected": true, "submission.reviewed": true, "task.accepted": true,
	"checkpoint.submitted": true, "checkpoint.verification_started": true,
	"checkpoint.usable": true, "checkpoint.rejected": true,
}

func emitDomain(ctx context.Context, tx pgx.Tx, kind, leaseID, entityID string, data any) error {
	if !domainEventKinds[kind] || !validID.MatchString(leaseID) || !validID.MatchString(entityID) {
		return ErrInvalid
	}
	payload, err := json.Marshal(struct {
		SchemaVersion string `json:"schema_version"`
		EntityID      string `json:"entity_id"`
		Data          any    `json:"data"`
	}{"1.0", entityID, data})
	if err != nil {
		return err
	}
	if len(payload) > 4096 {
		return ErrInvalid
	}
	_, err = tx.Exec(ctx, `INSERT INTO outbox(event_id,aggregate_id,kind,entity_id,payload)
        VALUES($1,$2,$3,$4,$5::jsonb)`, newID("event-"), leaseID, kind, entityID, string(payload))
	return err
}
